import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import { ref, onMounted, onUnmounted, computed } from 'vue';
import { useRouter } from 'vue-router';
import { useStore } from 'vuex';
import axios from 'axios';
import DOMPurify from 'dompurify';
import defaultAvatar from '@/assets/default-avatar.png';
import { API_CONFIG } from '@/config/config';
import { ElMessage } from 'element-plus';
import emojis from '@/utils/emojis'; // 导入表情数据

export default {
  setup() {
    const router = useRouter();
    const store = useStore();
    const moment = ref({});
    const currentUser = computed(() => store.state.user || {});
    const goToUser = () => router.push('/user');
    const goToUserProfile = userId => router.push(`/user/${userId}`);
    const openImagePreview = url => {
      window.open(url, '_blank');
    };
    const getVideoType = url => {
      if (url.endsWith('.mp4')) return 'video/mp4';
      if (url.endsWith('.webm')) return 'video/webm';
      if (url.endsWith('.ogg')) return 'video/ogg';
      return 'video/mp4';
    };
    const getFullUrl = path => {
      if (!path || path === defaultAvatar) return path;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const formatTime = timestamp => {
      const date = new Date(timestamp);
      return `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-` + `${date.getDate().toString().padStart(2, '0')} ` + `${date.getHours().toString().padStart(2, '0')}:` + `${date.getMinutes().toString().padStart(2, '0')}`;
    };
    const getTimeAgo = timestamp => {
      const now = Date.now();
      const diff = now - new Date(timestamp).getTime();
      const minutes = Math.floor(diff / 60000);
      const hours = Math.floor(minutes / 60);
      const days = Math.floor(hours / 24);
      if (minutes < 1) return '刚刚';
      if (minutes < 60) return `${minutes}分钟前`;
      if (hours < 24) return `${hours}小时前`;
      return `${days}天前`;
    };
    const sanitizeHtml = html => DOMPurify.sanitize(html);
    const fetchMomentDetail = async momentId => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/article/moment`, {
          params: {
            moment_id: momentId
          },
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        const momentData = response.data;
        moment.value = {
          ...momentData,
          showCommentInput: false,
          commentInput: '',
          comments: (momentData.comments || []).map(comment => ({
            ...comment,
            showReplyInput: false,
            replyInput: '',
            replies: comment.replies || [],
            showEmojiPicker: false // 为评论添加表情选择器状态
          })),
          showAllComments: false,
          isLiked: momentData.like_users?.includes(currentUser.value.id) || false,
          showEmojiPicker: false // 为评论输入框添加表情选择器状态
        };
      } catch (error) {
        console.error('获取动态详情失败:', error);
        ElMessage.error('加载动态详情失败');
      }
    };
    const toggleCommentInput = moment => {
      moment.showCommentInput = !moment.showCommentInput;
      moment.commentInput = '';
      moment.showEmojiPicker = false; // 关闭表情选择器
    };
    const postComment = async moment => {
      if (!moment.commentInput.trim()) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/post_comment`, {
          moment_id: moment.id,
          comment: moment.commentInput,
          comment_user_name: currentUser.value.username,
          comment_user_id: currentUser.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          moment.comments.unshift({
            id: response.data.id,
            comment: moment.commentInput,
            created_at: new Date().toISOString(),
            comment_user_name: currentUser.value.username,
            comment_user_photo: currentUser.value.photo,
            likes: 0,
            isLiked: false,
            replies: [],
            showReplyInput: false,
            replyInput: '',
            showEmojiPicker: false // 为新评论添加表情选择器状态
          });
          moment.stats.comments += 1;

          // 清空输入框但保持输入框显示
          moment.commentInput = '';
          moment.showEmojiPicker = false;

          // 添加评论成功的提示动画
          const commentEl = document.querySelector('.comments-list li:first-child');
          if (commentEl) {
            commentEl.classList.add('animate-pulse');
            setTimeout(() => {
              commentEl.classList.remove('animate-pulse');
            }, 1000);
          }
          ElMessage.success('评论发布成功');
        }
      } catch (error) {
        console.error('评论失败:', error);
        ElMessage.error('评论发布失败');
      }
    };
    const toggleReplyInput = comment => {
      comment.showReplyInput = !comment.showReplyInput;
      comment.replyInput = '';
      comment.showEmojiPicker = false; // 关闭表情选择器
    };
    const postReply = async (moment, comment) => {
      if (!comment.replyInput.trim()) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/post_reply`, {
          moment_id: moment.id,
          parent_comment_id: comment.id,
          comment: comment.replyInput,
          comment_user_id: currentUser.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          comment.replies.push({
            ...response.data.reply,
            comment_user_name: currentUser.value.username,
            comment_user_photo: currentUser.value.photo
          });

          // 清空输入框但保持输入框显示
          comment.replyInput = '';
          comment.showEmojiPicker = false;

          // 添加回复成功的提示动画
          const replyEl = document.querySelector(`.replies-list .reply-item:last-child`);
          if (replyEl) {
            replyEl.classList.add('animate-pulse');
            setTimeout(() => {
              replyEl.classList.remove('animate-pulse');
            }, 1000);
          }
          ElMessage.success('回复成功');
        }
      } catch (error) {
        console.error('回复失败:', error);
        ElMessage.error('回复失败');
      }
    };
    const likeMoment = async momentId => {
      const targetMoment = moment.value;
      if (!targetMoment) return;
      const originalIsLiked = targetMoment.isLiked;
      const originalLikes = targetMoment.stats.likes;
      try {
        targetMoment.isLiked = !targetMoment.isLiked;
        targetMoment.stats.likes += targetMoment.isLiked ? 1 : -1;

        // 添加点赞动画
        const likeIcon = document.querySelector('.like-container i.liked');
        if (likeIcon) {
          likeIcon.classList.add('animate-bounce');
          setTimeout(() => {
            likeIcon.classList.remove('animate-bounce');
          }, 500);
        }
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/like_moment`, {
          moment_id: momentId,
          user_id: currentUser.value.id,
          is_like: targetMoment.isLiked
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          },
          timeout: 5000
        });
        if (response.data.success) {
          if (!targetMoment.stats) {
            targetMoment.stats = {
              likes: 0
            };
          }
          targetMoment.isLiked = response.data.is_liked;
          targetMoment.stats.likes = response.data.likes_count;
          ElMessage.success(targetMoment.isLiked ? '点赞成功' : '已取消点赞');
          if (response.data.is_liked) {
            targetMoment.like_users = [...(targetMoment.like_users || []), currentUser.value.id];
          } else {
            targetMoment.like_users = (targetMoment.like_users || []).filter(id => id !== currentUser.value.id);
          }
        }
      } catch (error) {
        targetMoment.isLiked = originalIsLiked;
        targetMoment.stats.likes = originalLikes;
        console.error('点赞操作失败:', error);
        ElMessage.error(`操作失败: ${error.response?.data?.msg || '网络错误'}`);
      }
    };
    const likeComment = async (momentId, commentIndex) => {
      const comment = moment.value.comments[commentIndex];
      if (!comment) return;
      try {
        // 添加点赞动画
        const likeIcon = document.querySelector(`.comment-like i.liked:nth-child(${commentIndex + 1})`);
        if (likeIcon) {
          likeIcon.classList.add('animate-bounce');
          setTimeout(() => {
            likeIcon.classList.remove('animate-bounce');
          }, 500);
        }
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/like_comment`, {
          comment_id: comment.id,
          user_id: currentUser.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        comment.isLiked = response.data.is_liked;
        comment.likes = response.data.likes_count;
      } catch (error) {
        console.error('点赞失败:', error);
        ElMessage.error(`点赞失败: ${error.response?.data?.msg || '网络错误'}`);
      }
    };
    const deleteMoment = async momentId => {
      if (!confirm('确定要删除这条动态吗？')) return;
      try {
        await axios.post(`${API_CONFIG.BASE_URL}/article/delete/moment`, {
          moment_id: momentId
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        router.back();
        ElMessage.success('删除成功');
      } catch (error) {
        console.error('删除失败:', error);
        ElMessage.error('删除失败');
      }
    };

    // 删除评论方法
    const deleteComment = async (momentId, commentId, commentIndex) => {
      if (!confirm('确定要删除这条评论吗？')) return;
      try {
        await axios.post(`${API_CONFIG.BASE_URL}/article/delete/comment`, {
          comment_id: commentId
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });

        // 从列表中移除评论
        const commentEl = document.querySelector(`.comments-list li:nth-child(${commentIndex + 1})`);
        if (commentEl) {
          commentEl.style.opacity = '0';
          commentEl.style.transform = 'translateX(20px)';
          commentEl.style.transition = 'all 0.3s ease-out';
          setTimeout(() => {
            moment.value.comments.splice(commentIndex, 1);
            // 更新评论数量
            moment.value.stats.comments -= 1;
          }, 300);
        }
        ElMessage.success('评论已删除');
      } catch (error) {
        console.error('删除评论失败:', error);
        ElMessage.error('删除评论失败');
      }
    };

    // 删除回复方法
    const deleteReply = async (momentId, commentId, replyId, replyIndex) => {
      if (!confirm('确定要删除这条回复吗？')) return;
      try {
        await axios.post(`${API_CONFIG.BASE_URL}/article/delete/reply`, {
          reply_id: replyId
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });

        // 从列表中移除回复
        const replyEl = document.querySelector(`.replies-list .reply-item:nth-child(${replyIndex + 1})`);
        if (replyEl) {
          replyEl.style.opacity = '0';
          replyEl.style.transform = 'translateX(10px)';
          replyEl.style.transition = 'all 0.3s ease-out';
          setTimeout(() => {
            const comment = moment.value.comments.find(c => c.id === commentId);
            if (comment) {
              comment.replies.splice(replyIndex, 1);
            }
          }, 300);
        }
        ElMessage.success('回复已删除');
      } catch (error) {
        console.error('删除回复失败:', error);
        ElMessage.error('删除回复失败');
      }
    };
    const visibleComments = moment => {
      return moment.showAllComments ? moment.comments : moment.comments.slice(0, 3);
    };

    // 表情选择器相关方法
    const toggleEmojiPicker = (target, type) => {
      // 先关闭所有其他表情选择器
      if (type === 'comment') {
        // 关闭所有评论的表情选择器
        moment.value.comments.forEach(comment => {
          comment.showEmojiPicker = false;
        });
      } else {
        // 关闭主评论输入框的表情选择器
        moment.value.showEmojiPicker = false;
      }

      // 切换当前表情选择器状态
      target.showEmojiPicker = !target.showEmojiPicker;
    };
    const insertEmoji = (target, type, emoji) => {
      const inputField = type === 'comment' ? target.commentInput : target.replyInput;
      const newText = inputField + emoji;
      if (type === 'comment') {
        target.commentInput = newText;
      } else {
        target.replyInput = newText;
      }
    };

    // 监听路由参数变化，重新加载动态详情
    const routeChangeListener = router.afterEach((to, from) => {
      if (to.name === 'UserMomentDetail' && to.params.momentId !== from.params.momentId) {
        fetchMomentDetail(to.params.momentId);
      }
    });

    // 组件挂载时加载动态详情
    onMounted(() => {
      const momentId = router.currentRoute.value.params.momentId;
      if (momentId) {
        fetchMomentDetail(momentId);
      } else {
        ElMessage.error('动态ID不存在');
        router.back();
      }
    });

    // 组件卸载时清理监听器
    onUnmounted(() => {
      if (routeChangeListener) {
        routeChangeListener();
      }
    });
    return {
      moment,
      currentUser,
      defaultAvatar,
      goToUser,
      goToUserProfile,
      openImagePreview,
      getVideoType,
      getFullUrl,
      formatTime,
      getTimeAgo,
      sanitizeHtml,
      toggleCommentInput,
      postComment,
      toggleReplyInput,
      postReply,
      likeMoment,
      likeComment,
      deleteMoment,
      deleteComment,
      deleteReply,
      visibleComments,
      toggleEmojiPicker,
      insertEmoji,
      emojis
    };
  }
};
